from pathlib import Path
import hashlib,html,json,re,subprocess
ROOT=Path(__file__).resolve().parents[1]
film=json.loads((ROOT/'timeline.json').read_text(encoding='utf-8'))
candidates=[p for p in (ROOT/'out').glob('evidence-film-90s-v*.mp4') if p.stat().st_size>0]
source=max(candidates,key=lambda p:int(re.search(r'-v(\d+)\.mp4$',p.name).group(1)))
target=ROOT/'out/每個疑點都有來處_90秒完整版_Kore.mp4'
subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-i',str(source),'-map','0:v:0','-map','0:a:0','-c:v','copy','-af','loudnorm=I=-16:TP=-1.5:LRA=11','-c:a','aac','-b:a','192k','-ar','48000','-t','90','-movflags','+faststart',str(target)],check=True)
probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration,size:stream=index,codec_name,width,height,r_frame_rate,sample_rate,channels','-of','json',str(target)],text=True))
manifest={'file':target.name,'sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'media':probe,'voice':film['voice'],'sceneStarts':[s['start'] for s in film['scenes']],'narrationEnd':max(r['voiceEnd'] for r in film['measuredVoice']),'subtitleTiming':'Phrase-level interpolation inside measured audio clips; not word-level forced alignment.','mastering':'FFmpeg loudnorm target -16 LUFS, -1.5 dBTP, LRA 11; H.264 video stream copied.'}
(ROOT/'delivery-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
def mm(t):return f'{int(t)//60:02}:{int(t)%60:02}'
buttons=''.join(f'<button data-t="{s["start"]}" aria-label="跳至{mm(s["start"])} {html.escape(s["title"])}"><span>{mm(s["start"])}</span><b>{html.escape(s["title"])}</b></button>' for s in film['scenes'])
script=''.join(f'<section><h3>{mm(s["start"])}–{mm(s["end"])}　{html.escape(s["title"])}</h3><p>{html.escape(s["narration"] or "片尾保留四秒閱讀。")}</p></section>' for s in film['scenes'])
